BEGIN TRANSACTION;
CREATE TABLE entities ( id INTEGER PRIMARY KEY, type_id TEXT NOT NULL, layer TEXT, has_color_override INTEGER, color_r REAL, color_g REAL, color_b REAL, params TEXT);
CREATE TABLE entity_properties ( entity_id INTEGER NOT NULL, key TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY (entity_id, key), FOREIGN KEY (entity_id) REFERENCES entities(id) ON DELETE CASCADE);
CREATE TABLE layers ( name TEXT PRIMARY KEY, color_r REAL, color_g REAL, color_b REAL, line_weight REAL, visible INTEGER, locked INTEGER, line_type INTEGER);
COMMIT;
